function parsePeopleKeywordInput(value,{required=true}={}){const input=String(value??'').normalize('NFC');if(input.length>PEOPLE_MANUAL_IMPORT_LIMITS.inputChars)throw new Error(`이름·별칭 입력은 ${PEOPLE_MANUAL_IMPORT_LIMITS.inputChars}자 이하여야 합니다.`);const raw=input.split(/[,\n]/).map(item=>item.trim()).filter(Boolean);if(required&&!raw.length)throw new Error('찾을 인물 이름이나 별칭을 입력해주세요.');if(raw.length>PEOPLE_MANUAL_IMPORT_LIMITS.keywords)throw new Error(`이름·별칭은 ${PEOPLE_MANUAL_IMPORT_LIMITS.keywords}개 이하로 입력해주세요.`);const result=[],seen=new Set();for(const item of raw){if(item.length>PEOPLE_MANUAL_IMPORT_LIMITS.keywordChars)throw new Error(`이름·별칭 한 항목은 ${PEOPLE_MANUAL_IMPORT_LIMITS.keywordChars}자 이하여야 합니다.`);const key=peopleImportNorm(item);if(key&&!seen.has(key)){seen.add(key);result.push(item);}}if(required&&!result.length)throw new Error('찾을 인물 이름이나 별칭을 입력해주세요.');return result;}
