  async function click(button){const action=button.dataset.recoveryAction;if(!action)return false;if(controller.status().busy&&['check','repair','apply','force-prepare','force-apply'].includes(action))return true;if(action==='toggle'){controller.open=!controller.open;rerender();return true;}if(action==='force-prepare')await controller.prepareForce();if(action==='force-apply')await controller.applyForce();if(action==='check')await controller.diagnose();if(action==='repair')await controller.repair();if(action==='apply')await controller.apply();if(action==='copy')await copyTraceText(root.ownerDocument,controller.status().fixedJson);rerender();return true;}
