  async function change(target){if(target.dataset.recoveryField==='record'){controller.selectRecord(target.value);rerender();return true;}if(target.hasAttribute('data-recovery-file')){const file=target.files?.[0];if(file){if(file.size>350000){controller.error='JSON 파일은 350,000바이트 이하로 넣어주세요.';}else{controller.edit(await file.text());await controller.diagnose();}rerender();}return true;}return false;}
  let unsubscribe=null;return{render,click,input,change,start(){unsubscribe=controller.subscribe(()=>rerender());},destroy(){unsubscribe?.();controller.destroy();}};
