    const status=controller.status(),proposal=status.proposal;const location=status.key==='profile:personality'?'personality':status.key==='new:pattern'||status.key.startsWith('pattern:')?status.key:'global';if(location!==placement)return'';let field;try{field=resolvePeopleField(wikiController.snapshot(),person.id,status.key,getSettings());}catch{}
    if(!field&&appraisalAnchor)field={targetRefs:JSON.parse(appraisalAnchor.target)};
    const target=field?.targetRefs?.length?field.targetRefs.map(ref=>ref==='actor:user'?getUserName():wikiController.snapshot().documents[ref]?.title||ref).join(' · '):'인물 공통';
    let html='<section class="rp-section rp-people-field-ai" aria-live="polite"><div class="rp-section-head"><div><h3>AI 작성 · '+esc(status.label)+'</h3><small>'+esc(person.title)+' → '+esc(target)+'</small></div><button class="rp-button" data-people-action="field-ai-close">접기</button></div><p class="rp-small rp-muted">'+(status.key==='profile:personality'?'기본 성격 전체를 함께 작성 · 장기변화·수치·핀 유지':'이 항목만 작성')+' · 변경안을 확인한 뒤 반영 · 자동 재시도 OFF</p>';
    if(status.running)html+='<p><span class="rp-summary-mini-spinner"></span> '+(status.phase==='applying'?'변경안 저장 중…':'라이터가 근거를 확인하고 작성 중…')+'</p>';
