    if(proposal)html+='<div class="rp-command-diff"><div><small>변경 전</small><p>'+esc(display(proposal.before)||'없음')+'</p></div><div><small>변경 후</small><p>'+esc(display(proposal.after)||'없음')+'</p></div></div><p>'+esc(proposal.reason)+'</p>'+(proposal.issues.length?'<ul>'+proposal.issues.map(issue=>'<li>'+esc(issue)+'</li>').join('')+'</ul>':'')+'<button class="rp-button primary" data-people-action="field-ai-apply" '+(!proposal.changed||status.running?'disabled':'')+'>이 항목에 반영</button>';
