// V1 (1.00v): independent, collapsible long-term items with per-item manual/AI editing and pins.

function createPeoplePatternsUI({controller,esc,rerender,message,pinButton,fieldUI}){
  let draft=null,busy=false;const closed=new Set(),scopeKey=scope=>scope.scope.characterId+'\n'+scope.scope.chatKey;
  const button=(action,label,key='',disabled=false)=>'<button class="rp-button" data-person-pattern-action="'+action+'" data-pattern-key="'+esc(key)+'" '+(disabled?'disabled':'')+'>'+label+'</button>';
  function editor(){return'<div class="rp-person-pattern-editor"><label>내용<textarea data-person-pattern-field maxlength="400" '+(busy?'disabled':'')+'>'+esc(draft.text)+'</textarea></label><div class="rp-toolbar">'+button('save',busy?'저장 중…':'저장','',busy)+button('cancel','취소','',busy)+'</div></div>';}
  function render(person){
    const scope=controller.snapshot(),profile=scope.people?.profiles?.[person.id],patterns=profile?.longTermPatterns||[],open=!closed.has(person.id),locked=peopleItemPinned(scope,person.id,'longTermPatterns');
    const legacyPin=locked?'<button class="rp-button" data-people-action="pin" data-pin-key="longTermPatterns" aria-pressed="true">장기변화 전체 고정 해제</button>':'';
    let content=patterns.map((text,index)=>{const key=peoplePatternKey(text),pinned=peopleItemPinned(scope,person.id,key);return'<article class="rp-person-pattern-card" data-person-pattern="'+key+'"><div class="rp-section-head"><strong>장기변화 '+(index+1)+'</strong><div class="rp-toolbar">'+pinButton(key,'장기변화 '+(index+1))+button('edit','편집',key,busy||pinned)+button('remove','삭제',key,busy||pinned)+'</div></div><p>'+esc(text)+'</p>'+(draft?.personId===person.id&&draft.key===key?editor():'')+fieldUI.render(person,key)+'</article>';}).join('');
    if(!patterns.length)content='<p class="rp-small rp-muted">아직 등록된 장기변화가 없습니다.</p>';
    if(draft?.personId===person.id&&!draft.key)content+='<article class="rp-person-pattern-card rp-person-pattern-new"><div class="rp-section-head"><strong>새 장기변화</strong>'+fieldUI.button(person,'new:pattern')+'</div>'+editor()+'</article>';
    content+=fieldUI.render(person,'new:pattern');
    return'<section class="rp-section rp-person-long-term"><div class="rp-section-head"><h3><span class="rp-hash">#</span>장기변화</h3><div class="rp-toolbar"><span class="rp-badge">'+patterns.length+'개</span>'+legacyPin+button('add','추가','',busy||!profile||locked)+'<button class="rp-button" data-person-pattern-action="toggle" aria-expanded="'+open+'">'+(open?'접기':'펼치기')+'</button></div></div>'+(open?content+(!profile?'<p class="rp-small rp-muted">기본 성격을 먼저 등록하면 장기변화를 추가할 수 있습니다.</p>':''):'')+'</section>';
  }
  async function click(target,person){const action=target.dataset.personPatternAction;if(!action||!person)return false;if(action==='toggle'){if(closed.has(person.id))closed.delete(person.id);else closed.add(person.id);rerender();return true;}if(busy)return true;if(action==='cancel'){draft=null;rerender();return true;}
    const scope=controller.snapshot(),key=target.dataset.patternKey,profile=scope.people?.profiles?.[person.id];
    if(['add','edit'].includes(action)){if(!profile)return true;const value=action==='edit'?profile.longTermPatterns.find(text=>peoplePatternKey(text)===key):'';if(value===undefined)return true;if(peopleItemPinned(scope,person.id,action==='edit'?key:'longTermPatterns')){message('고정핀을 먼저 해제해주세요.');return true;}draft={personId:person.id,key:action==='edit'?key:null,text:value,expected:action==='edit'?value:null,scopeKey:scopeKey(scope)};closed.delete(person.id);rerender();return true;}
    const input=action==='remove'?{key,text:'',expected:profile?.longTermPatterns.find(text=>peoplePatternKey(text)===key),scopeKey:scopeKey(scope)}:draft;if(!input)return true;
    if(['save','remove'].includes(action)){busy=true;rerender();try{await controller.savePersonPatternSlot(person.id,input,{remove:action==='remove'});draft=null;message(action==='remove'?'장기변화를 삭제했습니다.':'장기변화를 저장했습니다.');}catch(error){if(draft&&error.appliedPattern){draft.key=error.appliedPatternKey;draft.expected=error.appliedPattern;}message(error.message);}finally{busy=false;rerender();}}return true;
  }
  return{render,click,input(target){if(target.dataset.personPatternField===undefined||!draft)return false;draft.text=target.value;return true;},hasDraft:()=>Boolean(draft),discard(){draft=null;},reset(){draft=null;closed.clear();}};
}

