 for(const entry of entries){refreshAssert(Array.isArray(entry.target_refs),'문서 항목의 대상 목록 형식이 잘못되었습니다.');const identity=JSON.stringify([entry.slot_id,[...entry.target_refs].sort(),entry.context_key]);if(!groups.has(identity))groups.set(identity,[]);groups.get(identity).push(entry);}
 for(const group of groups.values()){
  if(group.length===1){kept.push(group[0]);continue;}
  const signatures=[];
  for(const entry of group){
   // Each duplicate still passes the original field/owner/target/pin validator in an isolated draft.
   const draft=normalizeWikiScope(scope);refreshStageEntry(draft,documentId,entry);preparePeopleCommand(JSON.stringify({schema_version:1,request_ref:requestRef,profile_changes:[],entries:[refreshCommandEntry(entry)],issues:[]}),{scope:draft,documentId,requestRef,slots,settings});
   const sections=scope.documents[documentId].sections,previous=entry.slot_id==='core.identity'?resolveOverviewSection(sections,entry.section_id):entry.section_id?sections.find(section=>section.id===entry.section_id):sections.find(section=>section.provenance?.slotId===entry.slot_id&&refreshSame([...(section.provenance?.targetRefs||[])].sort(),[...entry.target_refs].sort())&&(section.provenance?.contextKey??null)===entry.context_key);
   signatures.push(JSON.stringify({...refreshCommandEntry(entry),section_id:previous?.id??null,text:entry.text.trim(),reason:entry.reason.trim(),basis:entry.basis,evidence_refs:[...entry.evidence_refs].sort(),evidence_quote:entry.evidence_quote}));
  }
  const label=refreshLabel(personRefreshEntryGroup(group[0]));
  if(signatures.every(signature=>signature===signatures[0])){kept.push(group[0]);issues.push(label+': 동일한 변경안이 반복되어 한 번만 검토합니다.');}
  else issues.push(label+': 같은 항목에 서로 다른 변경안이 있어 해당 변경안을 모두 제외했습니다. 기존 내용은 유지하며, 이 항목은 개별 작성으로 다시 확인해주세요.');
 }
