    if(own&&(running||status.message||status.error))html+='<div class="rp-summary-mission '+(status.phase==='failed'?'failed':status.phase==='completed'?'success':'')+'">'+(running?'<span class="rp-people-ring" aria-hidden="true"></span>':'')+'<div><strong>'+esc(status.stage||status.message||'요약 정리')+'</strong><small>'+elapsed+'초'+(status.message?' · '+esc(status.message):'')+'</small>'+(status.error?'<p>'+esc(status.error)+'</p>':'')+(running?'<span class="rp-people-dots"><i></i><i></i><i></i></span>':'')+'</div>'+(running?'<button class="rp-button" data-people-action="summary-cancel">취소</button>':'')+'</div>';
