  async function handleClick(button){if(await folderUI.click(button))return true;if(button.dataset.peopleAction==='select'&&folderUI.suppressSelect(button.dataset.value))return true;if(button.dataset.peopleAction==='import-lore-select'){await loreSelectorUI.open();return true;}if(await loreSelectorUI.click(button))return true;const startsEdit=['merge-open','emotion-add','emotion-edit','emotion-ai','emotion-remove','entry-edit','metric-edit','metric-create','profile-field-edit','entry-delete','metric-delete','edit','sexual-edit','sexual-clear','field-ai-start','metric-ai-start'].includes(button.dataset.peopleAction)||['add','edit','remove','clear','ai'].includes(button.dataset.personRecordAction)||['add','edit','remove'].includes(button.dataset.personCandidateAction)||['add','edit','remove'].includes(button.dataset.personPatternAction);if(startsEdit||button.dataset.commandAction==='open'){if(!confirmDiscard())return true;discardEdits();}if(await mergeUI.click(button,selected(),snapshot()))return true;if(await metricAIUI.click(button,selected()))return true;if(await fieldUI.click(button,selected()))return true;if(await emotionUI.click(button,selected(),snapshot()))return true;if(await entryEditor.click(button,selected()))return true;if(['add','ai'].includes(button.dataset.personRecordAction)){state.sectionClosed.delete(selected()?.id+'|'+button.dataset.group);if(button.dataset.group==='npc')state.relationOpen.add(selected()?.id);}if(['add','edit'].includes(button.dataset.personCandidateAction))state.sectionClosed.delete(selected()?.id+'|candidates');if(await patternsUI.click(button,selected()))return true;if(await candidateUI.click(button,selected()))return true;if(await recordsUI.click(button,selected(),snapshot()))return true;if(await commandUI.click(button,selected()))return true;const action=button.dataset.peopleAction;if(!action)return false;if(action==='section-toggle'){const group=button.dataset.fold;if(['speech','relationship','behavior','openness','appraisal','candidates','overview','knowledge','userRelationship','secret','suspicion'].includes(group)){const key=selected()?.id+'|'+group;if(state.sectionClosed.has(key))state.sectionClosed.delete(key);else state.sectionClosed.add(key);rerender();}return true;}if(action==='import-toggle'){state.importExpanded=!state.importExpanded;rerender();return true;}if(action==='summary-toggle'){state.summaryOpen=!state.summaryOpen;rerender();return true;}if(action==='summary-wiki'){const result=await summaryController?.summarizeWiki(button.dataset.value);message(result?.error||result?.message||'문서 요약을 처리했습니다.');rerender();return true;}if(action==='select'&&!selectDocument(button.dataset.value))return true;if(action==='pin'){if(state.pinning)return true;const id=selected()?.id,key=button.dataset.pinKey,enabled=!peopleItemPinned(snapshot(),id,key);state.pinning=true;try{await controller.setPersonPin(id,key,enabled);message(enabled?'이 항목을 고정했습니다.':'항목 고정을 해제했습니다.');}catch(error){message(error.message||'고정핀을 저장하지 못했습니다.');}finally{state.pinning=false;rerender();}return true;}if(action==='relation-toggle'){const id=selected()?.id;if(id){if(state.relationOpen.has(id))state.relationOpen.delete(id);else state.relationOpen.add(id);}rerender();return true;}if(['import-all','import-active','import-lore-active'].includes(action)){const mode=action==='import-all'?'all':action==='import-lore-active'?'lore-active':'active';await importController.run(mode);}else if(action==='import-keyword'){state.importOpen.keyword=true;await importController.runKeyword(state.importKeywords);}else if(action==='import-direct'){state.importOpen.direct=true;await importController.runDirect({name:state.directName,aliases:state.directAliases,material:state.directMaterial});}else if(action==='import-cancel')importController.cancel();else if(action==='import-apply'){try{const report=await importController.apply();message('선택한 인물을 반영했습니다 · 새 Character '+report.created+' · 프로필 '+report.initialized+(report.metadataUpdated>0?' · 별칭·태그 보완 '+report.metadataUpdated+'명':''));}catch(error){message(error.message||'인물 후보를 반영하지 못했습니다.');}}else if(action==='speech-toggle'){const id=selected()?.id;if(id){if(state.speechOpen.has(id))state.speechOpen.delete(id);else state.speechOpen.add(id);}}else if(action==='sexual-toggle'){const profile=snapshot().people.profiles[selected().id],field=button.dataset.field,enabled=!peopleSexualFieldEnabled(profile,field);controller.updateSexualEnabled(selected().id,field,enabled);if(!enabled&&state.sexualEdit===field){state.sexualEdit='';state.sexualDraft='';}message((field==='sexualDesire'?'성적 욕망':'이상성욕')+'을 이 인물에서 '+(enabled?'켰습니다.':'껐습니다. 저장 내용은 유지됩니다.'));}else if(action==='sexual-edit'){const profile=snapshot().people.profiles[selected().id],field=button.dataset.field;state.sexualEdit=field;state.sexualDraft=profile[field]?.text||'';}else if(action==='sexual-clear'){try{controller.updateSexualField(selected().id,button.dataset.field,'',{manualEdited:true});message('해당 성적 프로필 내용을 삭제했습니다.');}catch(error){message(error.message);}}else if(action==='sexual-cancel'){state.sexualEdit='';state.sexualDraft='';}else if(action==='sexual-generate-cancel'){importController?.cancel?.();}else if(action==='sexual-save'){const field=button.dataset.field;controller.updateSexualField(selected().id,field,state.sexualDraft,{manualEdited:true});state.sexualEdit='';state.sexualDraft='';message('성적 프로필을 저장했습니다.');}else if(action==='sexual-generate'){const result=await importController?.generateSexualField?.(button.dataset.value,button.dataset.field);message(result?.message||result?.error||'생성 요청을 처리했습니다.');}else if(action==='summary-people'){const result=await summaryController.summarizePeople(button.dataset.value);message(['completed','no-change'].includes(result.phase)?result.message:result.error||'People 요약 정리를 완료하지 못했습니다.');}else if(action==='summary-cancel'){summaryController?.cancel();}else if(action==='delete-person'){const person=snapshot()?.documents?.[button.dataset.value],profile=snapshot()?.people?.profiles?.[button.dataset.value];if(!person||!confirmPersonProfileDelete(document,peopleDisplayName(person,profile))){message('인물 삭제를 취소했습니다.');return true;}try{const report=await controller.deletePerson(person.id),profiles=snapshot()?.people?.profiles||{},fallback=characters().find(item=>item.id!==person.id&&profiles[item.id])||characters().find(item=>item.id!==person.id);state.selectedId=fallback?.id||'';state.editing=false;state.draft=null;message('인물 정보를 삭제했습니다 · 장기 변화 후보 '+report.removedCandidates+'건 정리 · Character Wiki와 관계 수치 유지');}catch(error){message(error.message||'인물 정보를 삭제하지 못했습니다.');}}else if(action==='select'){state.selectedId=button.dataset.value;state.editing=false;state.draft=null;}else if(action==='edit'){const profile=snapshot().people.profiles[selected().id];state.editing=true;state.draft={summary:profile.summary,coreTraits:profile.coreTraits.join(', '),values:profile.values.join(', '),emotionExpression:profile.emotionExpression,defenseResponse:profile.defenseResponse,intimacyStyle:profile.intimacyStyle,axes:{...profile.axes}};}else if(action==='cancel'){state.editing=false;state.draft=null;}else if(action==='save'){try{controller.updatePerson(selected().id,{...state.draft,coreTraits:peopleUiSplit(state.draft.coreTraits),values:peopleUiSplit(state.draft.values)});state.editing=false;state.draft=null;message('인물 정보를 저장했습니다.');}catch(error){message(error.message||'인물 정보를 저장하지 못했습니다.');}}else if(action==='candidate'){try{controller.reviewPersonCandidate(button.dataset.value,button.dataset.mode);message(button.dataset.mode==='approve'?'성격 변화를 반영했습니다.':button.dataset.mode==='reject'?'성격 변화 후보를 거부했습니다.':'성격 변화를 되돌렸습니다.');}catch(error){message(error.message||'성격 변화 후보를 처리하지 못했습니다.');}}rerender();return true;}
  function handleInput(target){if(!target?.matches?.('[data-person-search]'))state.typed=true;if(folderUI.input(target))return true;if(loreSelectorUI.input(target))return true;if(metricAIUI.input(target))return true;if(mergeUI.input(target))return true;if(emotionUI.input(target))return true;if(patternsUI.input(target))return true;if(candidateUI.input(target))return true;if(entryEditor.input(target))return true;if(target.hasAttribute?.('data-person-search')){query=target.value;focusSearch=true;searchCaret=target.selectionStart;if(!searchComposing)scheduleSearch();return true;}if(recordsUI.input(target,selected()))return true;if(commandUI.input(target,selected()))return true;if(target.dataset.peopleSexualStyle!==undefined){controller.updateSexualStyle(selected().id,Boolean(target.checked));message(target.checked?'이 인물의 발정 버전을 켰습니다. 다음 생성부터 강한 0.10.9 표현을 사용합니다.':'이 인물의 발정 버전을 껐습니다. 다음 생성부터 일반 0.10.7 표현을 사용합니다.');rerender();return true;}if(target.dataset.peopleImportCheck){importController?.toggle(target.dataset.peopleImportCheck,target.checked);return true;}const sexualField=target.dataset.peopleSexualField;if(sexualField){state.sexualDraft=target.value;return true;}const importField=target.dataset.peopleImportField;if(importField){if(importField==='keywords')state.importKeywords=target.value;else if(importField==='direct-name')state.directName=target.value;else if(importField==='direct-aliases')state.directAliases=target.value;else if(importField==='direct-material')state.directMaterial=target.value;return true;}const field=target.dataset.peopleField;if(!field||!state.draft)return false;if(peopleItemPinned(snapshot(),selected()?.id,field))return true;if(field.startsWith('axis:'))state.draft.axes[field.slice(5)]=Math.max(0,Math.min(100,Number(target.value)||0));else state.draft[field]=target.value;return true;}
  function handleToggle(target){if(target.hasAttribute?.('data-person-additional')){state.additionalOpen=Boolean(target.open);return true;}const key=target?.dataset?.peopleImportDetails;if(!['keyword','direct'].includes(key))return false;state.importOpen[key]=Boolean(target.open);return true;}
  let unsubscribe=()=>{};
  function renderSide(){return renderWithSnapshot(renderSideContent);}
  function render(){if(!hasDraftNow())state.typed=false;return renderWithSnapshot(()=>renderContent()+loreSelectorUI.render());}
  return{renderSide,render,handleClick,handleInput,handleToggle,handleComposition,mounted,selectDocument,discardEdits,selectedDocumentId:()=>selected()?.id||'',hasDraft:hasDraftNow,confirmDiscard,start(){loreSelectorUI.start();commandUI.start();fieldUI.start();metricAIUI.start();importRender?.dispose();importRender=createDeferredRender(document,()=>rerender());const importUnsubscribe=importController?.subscribe(()=>importRender.request())||(()=>{});unsubscribe=()=>{importUnsubscribe();importRender?.dispose();importRender=null;};},destroy(){unsubscribe();folderUI.destroy();loreSelectorUI.destroy();commandUI.destroy();fieldUI.destroy();metricAIUI.destroy();if(searchTimer!==null)clearTimeout(searchTimer);}};
