// V4 (1.0.4): expose bounded per-operation validation diagnostics from activity.
// V3 (0.10.50): expose the selected memory source and Director count for diagnostics.
// V2 (0.10.46): diagnostics show the effective per-stage dialogue budget.
// V1 (0.10.32): safe diagnostics expose relationship mode and Hypa gates without memory contents.
const clone = value => JSON.parse(JSON.stringify(value));

function stageModel(settings, stage) {
  const usage = settings.models.stages[stage];
  const preset = usage.mode === 'dedicated' ? usage.preset : settings.models.shared;
  return {
    source: usage.mode,
    contextCount: stageContextCount(settings,stage),
    contextUnit: stage==='writer'?'completed_turns':'messages',
    provider: preset.provider,
    model: preset.model,
    receiveContextAsPdf: Boolean(preset.receiveContextAsPdf),
  };
}

function recentAutomation(scope, limit = 20) {
  if (!scope?.automation?.records) return [];
  return Object.entries(scope.automation.records)
    .filter(([, record]) => !record.hidden)
    .map(([id, record]) => ({
      id,
      at: record.at || '',
      status: record.status || 'unknown',
      errorCode: record.errorCode || '',
      failureDetail: record.failureDetail || '',
      validation: record.validation ? clone(record.validation) : null,
      documentCount: Number(record.documentCount || 0),
      summary: record.summary ? {
        created: Number(record.summary.created || 0),
        updated: Number(record.summary.updated || 0),
        upsertedEntries: Number(record.summary.upsertedEntries || 0),
        removedEntries: Number(record.summary.removedEntries || 0),
        metricOpsIgnored: Number(record.summary.metricOpsIgnored || 0),
        metricOpsApplied: Number(record.summary.metricOpsApplied || 0),
        peopleInitialized:Number(record.summary.peopleInitialized||0),peopleObserved:Number(record.summary.peopleObserved||0),peopleReviewReady:Number(record.summary.peopleReviewReady||0),
        repairAttempted: Boolean(record.summary.repairAttempted),
        affected: Array.isArray(record.summary.affected) ? record.summary.affected.slice(0, 20).map(item => ({ type: item.type || '', title: item.title || '' })) : [],
      } : null,
    }))
    .sort((a, b) => String(b.at).localeCompare(String(a.at)))
    .slice(0, limit);
}

/** Builds a diagnostic snapshot without prompts, chat text, RP text, or credential plaintext. */
function createInspectorSnapshot({ store, keyStore, wikiController, autoWikiController, mainWikiHook, runtimeHooks, progressPanel }) {
  const settings = store.snapshot();
  const wikiStatus = wikiController.status();
  const scope = wikiController.snapshot();
  const keyStatus = keyStore.status();
  const providers = [...new Set(keyStatus.providers || [])].sort();
  return {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    plugin: {
      enabled: Boolean(settings.enabled),
      retrievalMode: settings.retrievalMode,
      relationshipOnlyMode:Boolean(settings.relationshipOnlyMode),
      hypaReferenceEnabled:settings.hypaReferenceEnabled!==false,
      hypaPlusReferenceEnabled:settings.hypaPlusReferenceEnabled!==false,
      hypaReferenceSource:selectedHypaSource(settings),
      directorMemoryLimit:directorMemoryLimit(settings),
      settings: clone(store.status()),
    },
    runtime: {
      hooks: clone(runtimeHooks.status()),
      missionPanel: clone(progressPanel.status()),
      autoWriter: clone(autoWikiController.status()),
    },
    models: {
      router: stageModel(settings, 'router'),
      director: stageModel(settings, 'director'),
      writer: stageModel(settings, 'writer'),
      credentialStore: {
        phase: keyStatus.phase,
        loaded: Boolean(keyStatus.loaded),
        blocked: Boolean(keyStatus.blocked),
        dirty: Boolean(keyStatus.dirty),
        backend: keyStatus.backend || '',
        configuredProviders: providers,
        error: keyStatus.error || '',
      },
    },
    retrieval: clone(mainWikiHook.last),
    wiki: {
      phase: wikiStatus.phase,
      error: wikiStatus.error || '',
      warning: wikiStatus.warning || '',
      writeBlocked: Boolean(wikiStatus.writeBlocked),
      scope: wikiStatus.scope ? clone(wikiStatus.scope) : null,
      storage: wikiStatus.store ? clone(wikiStatus.store) : null,
      revision: scope?.revision ?? null,
      documentCount: scope ? Object.keys(scope.documents || {}).length : 0,
      lastAutomation: scope?.automation?.lastStatus ? clone(scope.automation.lastStatus) : null,
      recentAutomation: recentAutomation(scope),
    },
    privacy: {
      includesCredentialPlaintext: false,
      includesPromptText: false,
      includesChatOrRpText: false,
      includesOtherPluginStorage: false,
    },
  };
}

async function copyInspectorSnapshot(document, snapshot) {
  const text = JSON.stringify(snapshot, null, 2);
  const clipboard = document?.defaultView?.navigator?.clipboard;
  if (typeof clipboard?.writeText === 'function') { await clipboard.writeText(text); return true; }
  if (!document || typeof document.createElement !== 'function' || typeof document.execCommand !== 'function') throw new Error('clipboard-unavailable');
  const textarea = document.createElement('textarea');
  textarea.value = text; textarea.setAttribute('readonly', '');
  textarea.style.position = 'fixed'; textarea.style.opacity = '0'; textarea.style.pointerEvents = 'none';
  document.body.appendChild(textarea);
  try { textarea.select(); if (!document.execCommand('copy')) throw new Error('clipboard-unavailable'); }
  finally { textarea.remove(); }
  return true;
}

