// V1 (1.0.10): chat-shared manual AI references live beside document management, with guarded autosave.

const manualSettingsCSS=`.rp-document-management-columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,380px);gap:16px;align-items:start}.rp-document-management-primary,.rp-document-management-reference{min-width:0}.rp-manual-ai-settings{padding:13px;border:1px solid var(--rp-line,#737b8b);border-radius:9px;background:var(--rp-bg,Canvas);color:var(--rp-ink,CanvasText)}.rp-manual-ai-settings h4{margin:0 0 10px;font-size:13px}.rp-manual-ai-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.rp-manual-ai-field{display:grid;gap:5px;font-size:11px;color:var(--rp-sub,GrayText);min-width:0}.rp-manual-ai-field[data-wide]{grid-column:1/-1}.rp-manual-ai-settings input,.rp-manual-ai-settings select{width:100%;min-width:0;font:inherit;padding:7px 8px;border:1px solid var(--rp-line,#737b8b);border-radius:6px;background:var(--rp-panel,Canvas);color:var(--rp-ink,CanvasText)}.rp-manual-ai-settings input:disabled{opacity:.5;cursor:not-allowed}.rp-manual-ai-help{display:block;margin-top:9px;line-height:1.65;font-size:11px;color:var(--rp-sub,GrayText)}.rp-manual-ai-state{min-height:18px;font-size:11px;color:var(--rp-sub,GrayText);margin:7px 0 0}.rp-manual-ai-error{font-size:11px;line-height:1.6;color:var(--rp-amber,#c89b64);margin:6px 0;overflow-wrap:anywhere}.rp-manual-ai-retry{display:flex;gap:6px;flex-wrap:wrap;margin-top:6px}.rp-manual-ai-retry .rp-button{font-size:11px;padding:4px 7px;min-height:28px}@media(max-width:850px){.rp-document-management-columns{grid-template-columns:1fr}}`;
const manualSettingsClone=value=>({...value}),manualSettingsSame=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
const manualSettingsScope=value=>{const scope=value?.scope||value;return scope?.characterId&&scope?.chatKey?String(scope.characterId)+'\n'+String(scope.chatKey):'';};

function createManualAISettingsUI({getOptions,saveOptions,getScope,esc,rerender=()=>{},message=()=>{}}){
 const states=new Map();let activeScope='',disposed=false;
 function current(personId){const scope=manualSettingsScope(getScope?.());if(!scope)return{scope:'',options:{...MANUAL_AI_REFERENCE_DEFAULTS},error:'현재 채팅을 확인한 뒤 설정할 수 있습니다.'};try{return{scope,options:normalizeManualAIReferenceOptions(getOptions(personId)),error:''};}catch(error){return{scope,options:{...MANUAL_AI_REFERENCE_DEFAULTS},error:String(error?.message||'참고 설정을 읽지 못했습니다.')};}}
 function entry(scope){let value=states.get(scope);if(!value){value={draft:null,baseline:null,saving:false,error:'',saved:false,needsSave:false,lastAttempt:null};states.set(scope,value);if(states.size>32)for(const[key,item]of states)if(key!==scope&&!item.draft&&!item.saving){states.delete(key);break;}}return value;}
 function status(personId){const now=current(personId),state=now.scope?entry(now.scope):null;let dirty=!!state?.draft;if(dirty&&!state.saving)try{dirty=!manualSettingsSame(normalizeManualAIReferenceOptions(state.draft),now.options);}catch{}return{ready:!!now.scope&&!now.error,pending:!!state?.saving||!!state?.needsSave||dirty,dirty,saving:!!state?.saving,error:now.error||state?.error||''};}
 function context(element,personId){const panel=element?.closest?.('[data-manual-ai-settings]'),id=panel?.dataset?.manualAiPerson??personId;let expected;try{expected=decodeURIComponent(panel?.dataset?.manualAiScope||'');}catch{return null;}const now=current(id);if(disposed||!expected||expected!==now.scope||now.error)return null;return{...now,personId:id,state:entry(expected),panel};}
 function render(personId){const now=current(personId);activeScope=now.scope;const state=entry(now.scope);if(state.draft&&!state.saving&&!now.error&&!state.error&&!state.needsSave)try{if(manualSettingsSame(normalizeManualAIReferenceOptions(state.draft),now.options)){state.draft=null;state.error='';state.baseline=null;}}catch{}const options=state.draft||now.options,disabled=state.saving||!now.scope||!!now.error,error=now.error||state.error,tag=disabled?'disabled':'',number=(key,label,max,off=false)=>`<label class="rp-manual-ai-field">${label}<input type="number" min="0" max="${max}" step="1" value="${esc(options[key])}" data-manual-ai-option="${key}" ${disabled||off?'disabled':''}></label>`;
  return`<style>${manualSettingsCSS}</style><section class="rp-manual-ai-settings" data-manual-ai-settings data-manual-ai-person="${esc(personId||'')}" data-manual-ai-scope="${esc(encodeURIComponent(now.scope))}" aria-busy="${state.saving}"><h4>전체·개별 AI 작성</h4><div class="rp-manual-ai-grid">${number('recentTurns','최근 대화 · 턴',STAGE_CONTEXT_MAX)}${number('memoryLimit','기억 참조 · 개수',HYPA_REFERENCE_MAX_ITEMS,options.memorySource==='off')}<label class="rp-manual-ai-field" data-wide>기억 종류<select data-manual-ai-option="memorySource" ${tag}>${[['off','사용 안 함'],['hypa','하이파'],['hypaplus','하이파 플러스']].map(([value,label])=>`<option value="${value}" ${options.memorySource===value?'selected':''}>${label}</option>`).join('')}</select></label></div><small class="rp-manual-ai-help">이 채팅의 모든 인물이 공유합니다. 1턴은 사용자 입력과 assistant 응답 한 쌍이며 최신 완료 대화를 포함합니다. 0턴은 채팅 제외입니다. 값 변경 후 저장하며, AI는 작성 버튼을 눌러야 실행합니다.</small><p class="rp-manual-ai-state" data-manual-ai-state role="status">${state.saving?'저장 중…':state.draft?'저장 대기':state.saved?'저장됨':''}</p>${error?`<p class="rp-manual-ai-error" role="alert">${esc(error)}</p><div class="rp-manual-ai-retry"><button class="rp-button" type="button" data-manual-ai-action="retry" ${disabled?'disabled':''}>저장 다시 시도</button><button class="rp-button" type="button" data-manual-ai-action="reset" ${state.saving?'disabled':''}>저장값 불러오기</button></div>`:''}</section>`;
 }
 function input(element,personId){const key=element?.dataset?.manualAiOption;if(!['recentTurns','memorySource','memoryLimit'].includes(key))return false;const seen=context(element,personId);if(!seen||seen.state.saving)return true;const state=seen.state;if(!state.draft){state.draft=manualSettingsClone(seen.options);state.baseline=manualSettingsClone(seen.options);}state.draft[key]=key==='memorySource'?element.value:element.value.trim()===''?'':Number(element.value);state.error='';state.saved=false;if(key==='memorySource'){const count=seen.panel?.querySelector('[data-manual-ai-option="memoryLimit"]');if(count)count.disabled=element.value==='off';}const label=seen.panel?.querySelector('[data-manual-ai-state]');if(label)label.textContent='저장 대기';for(const node of seen.panel?.querySelectorAll('.rp-manual-ai-error,.rp-manual-ai-retry')||[])node.remove();return true;}
 async function commit(seen,{retry=false}={}){const state=seen.state;if(state.saving||!state.draft)return true;try{const options=normalizeManualAIReferenceOptions(state.draft),fresh=current(seen.personId);if(fresh.scope!==seen.scope||fresh.error)throw new Error('채팅이 바뀌어 참고 설정을 저장하지 않았습니다.');if(state.baseline&&!manualSettingsSame(state.baseline,fresh.options)&&!(state.needsSave&&manualSettingsSame(state.lastAttempt,fresh.options))&&!(retry&&manualSettingsSame(options,fresh.options)))throw new Error('참고 설정이 다른 작업에서 바뀌었습니다. 저장값을 불러온 뒤 다시 수정해주세요.');if(manualSettingsSame(options,fresh.options)&&!state.needsSave&&!state.error&&!retry){state.draft=null;state.baseline=null;state.error='';return true;}state.saving=true;state.error='';state.lastAttempt=manualSettingsClone(options);if(activeScope===seen.scope)rerender();await saveOptions(seen.personId,options,seen.scope);state.draft=null;state.baseline=null;state.saved=true;state.needsSave=false;state.lastAttempt=null;if(!disposed&&activeScope===seen.scope&&manualSettingsScope(getScope?.())===seen.scope)message('이 채팅의 AI 참고 설정을 저장했습니다.');}catch(error){if(state.saving)state.needsSave=true;state.error=String(error?.message||'AI 참고 설정을 저장하지 못했습니다.');if(!disposed&&activeScope===seen.scope)message(state.error);}finally{state.saving=false;if(!disposed&&activeScope===seen.scope)rerender();}return true;}
 async function change(element,personId){if(!['recentTurns','memorySource','memoryLimit'].includes(element?.dataset?.manualAiOption))return false;const seen=context(element,personId);if(!seen)return true;if(!seen.state.saving)input(element,personId);return commit(seen);}
 async function click(element,personId){const action=element?.dataset?.manualAiAction;if(!['retry','reset'].includes(action))return false;const seen=context(element,personId);if(!seen||seen.state.saving)return true;if(action==='reset'){if(seen.state.needsSave){seen.state.draft=manualSettingsClone(seen.options);seen.state.error='메모리에 반영된 설정의 저장을 먼저 다시 시도해주세요.';}else{seen.state.draft=null;seen.state.baseline=null;seen.state.error='';}rerender();return true;}return commit(seen,{retry:true});}
 return{render,input,change,click,status,destroy(){disposed=true;states.clear();}};
}

